package e.e.a;
import android.app.Activity;import android.view.*;import java.util.*;import java.lang.reflect.*;
public class MenuPlacementTest {
 public static class Host extends Activity {public int E;public String A="";Host(int type){E=type;}}
 static class Item implements InvocationHandler{int id,order,group;CharSequence title;boolean checked,checkable,visible=true,enabled=true;Object icon;MenuItem.OnMenuItemClickListener listener;MenuItem proxy;Item(int g,int i,int o,CharSequence t){group=g;id=i;order=o;title=t;proxy=(MenuItem)Proxy.newProxyInstance(MenuItem.class.getClassLoader(),new Class[]{MenuItem.class},this);}public Object invoke(Object p,Method m,Object[] a){switch(m.getName()){case "getItemId":return id;case "getOrder":return order;case "getGroupId":return group;case "getTitle":return title;case "getIcon":return icon;case "isChecked":return checked;case "isCheckable":return checkable;case "isVisible":return visible;case "isEnabled":return enabled;case "setChecked":checked=(Boolean)a[0];return proxy;case "setCheckable":checkable=(Boolean)a[0];return proxy;case "setVisible":visible=(Boolean)a[0];return proxy;case "setEnabled":enabled=(Boolean)a[0];return proxy;case "setOnMenuItemClickListener":listener=(MenuItem.OnMenuItemClickListener)a[0];return proxy;case "toString":return title;default:return m.getReturnType()==MenuItem.class?proxy:null;}}}
 static class Items implements InvocationHandler{final List<Item> rows=new ArrayList<>();Menu proxy=(Menu)Proxy.newProxyInstance(Menu.class.getClassLoader(),new Class[]{Menu.class},this);public Object invoke(Object p,Method m,Object[] a){switch(m.getName()){case "add":Item item=new Item((Integer)a[0],(Integer)a[1],(Integer)a[2],(CharSequence)a[3]);rows.add(item);rows.sort((x,y)->Integer.compare(x.order,y.order));return item.proxy;case "size":return rows.size();case "getItem":return rows.get((Integer)a[0]).proxy;case "clear":rows.clear();return null;case "removeItem":rows.removeIf(i->i.id==(Integer)a[0]);return null;case "findItem":for(Item i:rows)if(i.id==(Integer)a[0])return i.proxy;return null;default:return null;}}}
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}public static void main(String[] args){for(int type:new int[]{4,8,5,9}){Items menu=new Items();if(type==5||type==9)menu.proxy.add(0,1,0,"selection");menu.proxy.add(0,0x7f0f0201,0,"continuous").setCheckable(true);menu.proxy.add(0,0x7f0f0120,0,"settings");menu.proxy.add(0,18120,50,"old shuffle");ListActions.adjustHistoryMenu(new Host(type),menu.proxy);check(menu.rows.get(0).id==0x7f0f0201&&menu.rows.get(1).id==18120,"shuffle must follow continuous");check(menu.rows.stream().filter(i->i.id==18120).count()==1,"shuffle must not duplicate");check(menu.rows.get(0).listener!=null&&menu.rows.get(1).listener!=null,"both controls must be actionable");check(menu.proxy.findItem(18121)==null,"sort belongs in list header");check(type==4||type==8?menu.rows.get(2).id==0x7f0f0120:menu.rows.get(2).id==1&&menu.rows.get(3).id==0x7f0f0120,"history and mylist options follow requested order");ListActions.adjustHistoryMenu(new Host(type),menu.proxy);check(menu.rows.stream().filter(i->i.id==18120).count()==1,"repeat creation is stable");check(menu.rows.stream().filter(i->i.id==18121).count()==0,"sort menu stays absent");menu.rows.get(1).listener.onMenuItemClick(menu.rows.get(1).proxy);check(com.sauzask.nicoid.NicoidVideoListActivity.I&&com.sauzask.nicoid.NicoidVideoListActivity.J==2,"shuffle enables native queue in random mode");ListActions.adjustHistoryMenu(new Host(type),menu.proxy);check(menu.rows.get(1).checked&&!menu.rows.get(0).checked,"shuffle selected independently of continuous checkbox");menu.rows.get(1).listener.onMenuItemClick(menu.rows.get(1).proxy);check(!com.sauzask.nicoid.NicoidVideoListActivity.I,"shuffle can be disabled");}System.out.println("Playback menu placement: "+checks+" history/mylist checks passed");}
}
